cpp.setup:
auto* rootLayout = new QVBoxLayout(%PARENT%);
rootLayout->setContentsMargins(0, 0, 0, 0);
auto* card = new fluent::layout::Card(%PARENT%);
rootLayout->addWidget(card);
auto* cardLayout = new QVBoxLayout(card);
cardLayout->setContentsMargins(12, 10, 12, 12);
cardLayout->setSpacing(8);
auto* control = new fluent::navigation::TabView(card);
auto* pageHost = new fluent::navigation::StackContentHost(card);
pageHost->setTransitionAnimationEnabled(false);
control->addTab(fluent::navigation::TabViewItem(QStringLiteral("Overview"), Typography::Icons::Home));
control->addTab(fluent::navigation::TabViewItem(QStringLiteral("Metrics"), Typography::Icons::Info));
control->addTab(fluent::navigation::TabViewItem(QStringLiteral("Logs"), Typography::Icons::Document));
control->setSelectedIndex(0);
const auto syncPages = [control, pageHost] {
    pageHost->releaseAllPages();
    for (int i = 0; i < control->tabCount(); ++i) {
        const auto tab = control->tabAt(i);
        auto* page = new fluent::layout::Card(pageHost);
        page->setAppearance(fluent::layout::Card::LayerAlt);
        auto* pageLayout = new QVBoxLayout(page);
        pageLayout->setContentsMargins(14, 12, 14, 12);
        pageLayout->setSpacing(4);
        auto* heading = new fluent::textfields::Label(tab.text, page);
        heading->setFluentTypography(Typography::FontRole::BodyStrong);
        auto* body = new fluent::textfields::Label(QStringLiteral("Hosted content synchronized with tab %1.").arg(i + 1), page);
        body->setFluentTypography(Typography::FontRole::Caption);
        body->setTextColorRole(fluent::textfields::Label::TextColorRole::Secondary);
        body->setWordWrap(true);
        pageLayout->addWidget(heading);
        pageLayout->addWidget(body);
        pageLayout->addStretch(1);
        pageHost->insertPage(i, page);
    }
    if (control->selectedIndex() >= 0 && control->selectedIndex() < pageHost->count())
        pageHost->setCurrentIndex(control->selectedIndex(), 0, false);
};
QObject::connect(control, &fluent::navigation::TabView::tabsChanged, pageHost, syncPages);
QObject::connect(control, &fluent::navigation::TabView::tabMoved, pageHost, [syncPages](int, int) { syncPages(); });
QObject::connect(control, &fluent::navigation::TabView::currentChanged, pageHost, [pageHost](int index) {
    if (index >= 0 && index < pageHost->count())
        pageHost->setCurrentIndex(index, 0, false);
});
QObject::connect(control, &fluent::navigation::TabView::tabCloseRequested, control, [control](int index) { control->closeTab(index); });
QObject::connect(control, &fluent::navigation::TabView::addTabRequested, control, [control] {
    control->setSelectedIndex(control->addTab(fluent::navigation::TabViewItem(QStringLiteral("Tab %1").arg(control->tabCount() + 1), Typography::Icons::Document)));
});
syncPages();
cardLayout->addWidget(control);
cardLayout->addWidget(pageHost, 1);
